## 순수 함수와 불변성 기본 개념

### 순수 함수 (Pure Functions)
```javascript
// ❌ 순수하지 않은 함수 (side effect 있음)
let counter = 0;
function impureIncrement() {
    counter++; // 외부 변수 변경
    return counter;
}

// ✅ 순수 함수 (같은 입력 → 같은 출력, side effect 없음)
function pureAdd(a, b) {
    return a + b; // 외부 상태에 의존하지 않음
}

function pureIncrement(value) {
    return value + 1; // 새로운 값 반환
}
```

### 불변성 (Immutability)
```python
# ❌ 가변성 (원본 데이터 변경)
def add_item_mutable(items, new_item):
    items.append(new_item)  # 원본 리스트 변경
    return items

# ✅ 불변성 (새로운 데이터 생성)
def add_item_immutable(items, new_item):
    return [*items, new_item]  # 원본 유지, 새 리스트 반환

# JavaScript 예시
const original = [1, 2, 3];
const updated = [...original, 4]; // [1, 2, 3, 4], 원본은 그대로
```

## React 앱에서의 상태 관리 적용

### 1. Redux와 함수형 상태 관리
```javascript
// 순수 함수로 만든 reducer
const todoReducer = (state = [], action) => {
    switch (action.type) {
        case 'ADD_TODO':
            // 불변성 유지: 새 배열 생성
            return [...state, {
                id: Date.now(),
                text: action.text,
                completed: false
            }];

        case 'TOGGLE_TODO':
            // map으로 불변 업데이트
            return state.map(todo =>
                todo.id === action.id
                    ? { ...todo, completed: !todo.completed }
                    : todo
            );

        case 'REMOVE_TODO':
            // filter로 불변 삭제
            return state.filter(todo => todo.id !== action.id);

        default:
            return state; // 항상 같은 참조 반환
    }
};

// 순수 함수 selector
const getCompletedTodos = (todos) => 
    todos.filter(todo => todo.completed);

const getTodoCount = (todos) => 
    ({ total: todos.length, completed: getCompletedTodos(todos).length });
```

### 2. React Hook에서의 불변성
```javascript
import { useState, useMemo, useCallback } from 'react';

function TodoApp() {
    const [todos, setTodos] = useState([]);
    const [filter, setFilter] = useState('all');

    // 순수 함수로 필터링 로직 분리
    const getFilteredTodos = useCallback((todos, filter) => {
        switch (filter) {
            case 'completed': return todos.filter(t => t.completed);
            case 'active': return todos.filter(t => !t.completed);
            default: return todos;
        }
    }, []);

    // 메모이제이션으로 성능 최적화
    const filteredTodos = useMemo(() => 
        getFilteredTodos(todos, filter), [todos, filter, getFilteredTodos]
    );

    const addTodo = useCallback((text) => {
        setTodos(prev => [...prev, {
            id: Date.now(),
            text,
            completed: false
        }]);
