## 데이터 파이프라인 처리에서의 적용

### 1. Python에서의 함수형 데이터 처리
```python
from functools import reduce
from typing import List, Dict, Any

# 순수 함수들로 구성된 데이터 변환 파이프라인
def clean_data(raw_data: List[Dict]) -> List[Dict]:
    """원본 데이터를 정제하는 순수 함수"""
    return [
        {**item, 'name': item['name'].strip().title()}
        for item in raw_data
        if item.get('name') and item.get('age', 0) > 0
    ]

def add_category(data: List[Dict]) -> List[Dict]:
    """카테고리 추가하는 순수 함수"""
    def categorize_by_age(person):
        age = person['age']
        category = 'child' if age < 18 else 'adult' if age < 65 else 'senior'
        return {**person, 'category': category}

    return list(map(categorize_by_age, data))

def filter_by_category(data: List[Dict], category: str) -> List[Dict]:
    """특정 카테고리 필터링하는 순수 함수"""
    return list(filter(lambda x: x['category'] == category, data))

def calculate_stats(data: List[Dict]) -> Dict[str, Any]:
    """통계 계산하는 순수 함수"""
    if not data:
        return {'count': 0, 'avg_age': 0}

    total_age = reduce(lambda sum_age, person: sum_age + person['age'], data, 0)
    return {
        'count': len(data),
        'avg_age': total_age / len(data),
        'categories': list(set(person['category'] for person in data))
    }

# 함수 합성을 통한 파이프라인 구성
def process_user_data(raw_data: List[Dict], target_category: str = None) -> Dict[str, Any]:
    """전체 데이터 처리 파이프라인"""
    # 함수들을 체이닝하여 데이터 변환
    cleaned = clean_data(raw_data)
    categorized = add_category(cleaned)

    if target_category:
        filtered = filter_by_category(categorized, target_category)
        return {
            'processed_data': filtered,
            'stats': calculate_stats(filtered)
        }

    return {
        'processed_data': categorized,
        'stats': calculate_stats(categorized)
    }

# 실제 사용 예시
raw_users = [
    {'name': ' alice ', 'age': 25},
    {'name': 'bob', 'age': 17},
    {'name': '', 'age': 30},  # 제거될 데이터
    {'name': 'charlie', 'age': 70}
]

result = process_user_data(raw_users, 'adult')
print(result)
```

### 2. JavaScript에서의 비동기 데이터 처리
```javascript
// 순수 함수들로 구성된 API 데이터 처리
const transformApiResponse = (response) => ({
    ...response,
    timestamp: Date.now(),
    processed: true
});

const validateData = (data) => 
    data.filter(item => item.id && item.name);

const enrichData = async (items) => {
    // 각 아이템을 병렬로 처리 (순수 함수 활용)
    return Promise.all(
        items.map(async item => ({
            ...item,
            metadata: await fetchMetadata(item.id),
            score: calculateScore(item) // 순수 함수
        }))
    );
};

// 함수 합성을 통한 비동기 파이프라인
const processApiData = async (apiUrl) => {
    try {
        const response = await fetch(apiUrl);
        const rawData = await response.json();

        // 순수 함수들을 체이닝
        const transformed = transformApiResponse(rawData);
        const validated = validateData(transformed.data);
        const enriched = await enrichData(validated);

        return {
            success: true,
            data: enriched,
            meta: {
                count: enriched.length,
                processedAt: Date.now()
            }
        };
    } catch (error) {
        // 에러도 불변 객체로 반환
        return {
            success: false,
            error: error.message,
            data: null
        };
    }
};
```

## 실제 프로젝트에서의 장점

### 1. 예측 가능성과 테스트 용이성
```javascript
// 순수 함수는 테스트하기 매우 쉬움
describe('Todo functions', () => {
    test('addTodo should not mutate original array', () => {
        const original = [{ id: 1, text: 'test' }];
        const result = addTodo(original, 'new todo');

        expect(original).toEqual([{ id: 1, text: 'test' }]); // 원본 유지
        expect(result).toHaveLength(2); // 새 배열에 추가됨
    });
});
```

### 2. 디버깅과 시간 여행 디버깅
Redux DevTools 같은 도구로 상태 변화 추적이 가능한 이유가 바로 불변성 덕분이야.

### 3. 병렬 처리와 성능 최적화
불변 데이터는 여러 스레드에서 안전하게 접근할 수 있어서 병렬 처리에 유리하다.

